import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = pd.NaT

    # Build initial state dict: user_id -> {email, status, status_ts}
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    if pd.isna(high_ts):
        events = cdc_events.copy()
    else:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort deterministically by (event_ts, event_seq)
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    for row in events.itertuples(index=False):
        uid = row.user_id
        op = row.op
        ts = row.event_ts
        ev_email = row.email

        current = state.get(uid)

        if op == "D":
            if current is None:
                # Delete on unknown user: create a deleted record with event email
                # (no prior email to preserve)
                state[uid] = {
                    "email": ev_email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                # Preserve existing email, just update status/status_ts
                state[uid] = {
                    "email": current["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if current is None or current["status"] == "ACTIVE":
                state[uid] = {
                    "email": ev_email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # current status == 'DELETED'
                deletion_ts = current["status_ts"]
                threshold = deletion_ts + timedelta(days=7)
                if ts > threshold:
                    # Resurrection
                    state[uid] = {
                        "email": ev_email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                # else: discard, no change
        # else: unknown op, ignore

    # Build output DataFrame
    records = []
    for uid, vals in state.items():
        records.append({
            "user_id": uid,
            "email": vals["email"],
            "status": vals["status"],
            "status_ts": vals["status_ts"],
        })

    new_snapshot = pd.DataFrame(records, columns=["user_id", "email", "status", "status_ts"])

    # Ensure dtypes
    if len(new_snapshot) > 0:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])
    else:
        new_snapshot = pd.DataFrame({
            "user_id": pd.Series(dtype="int64"),
            "email": pd.Series(dtype="object"),
            "status": pd.Series(dtype="object"),
            "status_ts": pd.Series(dtype="datetime64[us]"),
        })

    return {"new_snapshot": new_snapshot}
